#!/usr/bin/env bash
# Build the H109 slow example library one module at a time, each on one core
# (LEAN_NUM_THREADS=1) under its own timeout (H134: at most 600 s per module), in import
# order, so a module that outgrows its budget is named instead of timing out the whole
# library. Modules come from SoliditySlowExamples.lean (generated by register.sh), so the
# list never needs editing here. Run after `lake build Solidity SolidityExamples`: a slow
# module's budget then covers only itself (and any not-yet-built import outside those).
#
# Usage: scripts/ci/build-slow-examples.sh [--list]
#   --list  print the modules in build order and exit
# Environment: SLOW_EXAMPLE_BUDGET_S (default 600; values above 600 are refused).
# Prints "PASS|FAIL|TIMEOUT <module> <seconds>s" per module; exit 0 all passed, 1 a build
# failed or timed out, 2 usage error.
set -uo pipefail
root=$(git rev-parse --show-toplevel) || exit 2
cd "$root" || exit 2
export PATH="$HOME/.elan/bin:$PATH"
budget=${SLOW_EXAMPLE_BUDGET_S:-600}
case "$budget" in ''|*[!0-9]*) echo "build-slow-examples: bad budget" >&2; exit 2;; esac
[ "$budget" -le 600 ] || { echo "build-slow-examples: budget $budget s exceeds 600 s (H134); ESCALATE instead" >&2; exit 2; }
list=0
case "${1:-}" in
  --list) list=1; [ $# -eq 1 ] || { echo "usage: build-slow-examples.sh [--list]" >&2; exit 2; };;
  "") ;;
  *) echo "usage: build-slow-examples.sh [--list]" >&2; exit 2;;
esac
order=$(python3 - <<'PY'
import pathlib, re, sys
imp = re.compile(r"^\s*(?:(?:public|private|meta)\s+)*import(?:\s+all)?\s+(.+)$")
def imports(path):
    out = []
    for line in path.read_text().splitlines():
        m = imp.match(line)
        if m: out += m.group(1).split("--", 1)[0].split()
    return out
slow = imports(pathlib.Path("SoliditySlowExamples.lean"))
if not slow: sys.exit("build-slow-examples: no modules in SoliditySlowExamples.lean")
deps = {m: [d for d in imports(pathlib.Path(m.replace(".", "/") + ".lean")) if d in slow] for m in slow}
order, state = [], {}
def visit(m):
    if state.get(m) == 2: return
    if state.get(m) == 1: sys.exit("build-slow-examples: import cycle at " + m)
    state[m] = 1
    for d in sorted(deps[m]): visit(d)
    state[m] = 2; order.append(m)
for m in sorted(slow): visit(m)
print("\n".join(order))
PY
) || exit 2
if [ "$list" = 1 ]; then echo "$order"; exit 0; fi
failed=0
while read -r m; do
  [ -n "$m" ] || continue
  start=$(date +%s)
  LEAN_NUM_THREADS=1 timeout --kill-after=10s "${budget}s" lake build "$m" </dev/null; st=$?
  secs=$(( $(date +%s) - start ))
  if [ "$st" -eq 0 ]; then echo "PASS $m ${secs}s"
  elif [ "$st" -eq 124 ] || [ "$st" -eq 137 ]; then failed=1; echo "TIMEOUT $m ${secs}s (budget ${budget}s)"
  else failed=1; echo "FAIL $m ${secs}s (exit $st)"; fi
done <<<"$order"
exit "$failed"
